begin;
set local search_path=public,extensions;
select extensions.no_plan();
select extensions.is((select monthly_fee from public.saas_plans where product_id=(select id from public.platform_products where code='menu') and code='cardapio'),29.90::numeric,'Cardápio monthly price');
select extensions.is((select monthly_fee from public.saas_plans where product_id=(select id from public.platform_products where code='menu') and code='foundation'),49.90::numeric,'Encomendas monthly price');
insert into public.barbershops(id,name,slug,segment) values('dd100000-0000-4000-8000-000000000001','Offers fixture','offers-fixture','Restaurante');
insert into public.saas_clients(id,name,segment,contact_name,owner_email,origin,plan,monthly_fee,status,barbershop_id)
values('dd200000-0000-4000-8000-000000000001','Offers fixture','Restaurante','Fixture','offers@example.invalid','Teste','Encomendas',49.90,'Ativo','dd100000-0000-4000-8000-000000000001');
insert into public.billing_customers(saas_client_id,billing_email) values('dd200000-0000-4000-8000-000000000001','offers@example.invalid');
insert into public.platform_subscriptions(billing_customer_id,product_id,plan_id,status,base_amount,current_period_end)
select customer.id,product.id,plan.id,'trial',49.90,now()+interval '7 days' from public.billing_customers customer,public.platform_products product,public.saas_plans plan
where customer.saas_client_id='dd200000-0000-4000-8000-000000000001' and product.code='menu' and plan.product_id=product.id and plan.code='foundation';
insert into private.billing_signups(id,tax_document,business_name,responsible_name,email,phone,cycle,payment_method,base_monthly_cents,cycle_months,discount_bps,total_cents,terms_version,management_token_hash,product_code,barbershop_id,saas_client_id,trial_ends_at)
values('dd300000-0000-4000-8000-000000000001','00000000001301','Offers fixture','Fixture','offers@example.invalid','11999999999','monthly','pix',4990,1,0,4990,'fixture','offers-fixture-token','menu','dd100000-0000-4000-8000-000000000001','dd200000-0000-4000-8000-000000000001',now()+interval '7 days');
insert into public.business_whatsapp_shares(barbershop_id,phone) values('dd100000-0000-4000-8000-000000000001','5511999999999');
insert into public.online_menus(id,barbershop_id,slug,title,template_code,settings_completed_at,visual_identity,weekly_hours,accepted_payment_methods,accepts_delivery,accepts_pickup)
values('dd400000-0000-4000-8000-000000000001','dd100000-0000-4000-8000-000000000001','offers-fixture','Offers fixture','pizzeria',now(),'{"primary_color":"#111827","accent_color":"#f59e0b"}','{"weekdays":[1,2,3],"opens_at":"10:00","closes_at":"22:00"}',array['pix'],false,true);
insert into public.menu_categories(id,barbershop_id,menu_id,name) values('dd500000-0000-4000-8000-000000000001','dd100000-0000-4000-8000-000000000001','dd400000-0000-4000-8000-000000000001','Fixture');
insert into public.menu_items(id,barbershop_id,category_id,name) values('dd600000-0000-4000-8000-000000000001','dd100000-0000-4000-8000-000000000001','dd500000-0000-4000-8000-000000000001','Fixture item');
insert into public.menu_item_prices(id,barbershop_id,menu_item_id,label,price) values('dd700000-0000-4000-8000-000000000001','dd100000-0000-4000-8000-000000000001','dd600000-0000-4000-8000-000000000001','500 g',25);
insert into auth.users(id,instance_id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
values('dd800000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','offers-owner@example.invalid','{}','{}',now(),now());
insert into public.profiles(id,barbershop_id,full_name,role,active) values('dd800000-0000-4000-8000-000000000001','dd100000-0000-4000-8000-000000000001','Offers owner','owner',true);
create temporary table offers_original_boundary as select trial_started_at,trial_ends_at,access_until from private.billing_signups where id='dd300000-0000-4000-8000-000000000001';
select extensions.ok(private.menu_has_orders('dd100000-0000-4000-8000-000000000001'),'legacy full plan keeps orders');
select public.backend_billing_change_offer('dd100000-0000-4000-8000-000000000001','cardapio',(select updated_at from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'));
select extensions.is((select total_cents from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'),2990,'downgrade changes next monthly price');
select extensions.is((select plan from public.saas_clients where id='dd200000-0000-4000-8000-000000000001'),'Cardápio','client record follows actual plan');
select extensions.ok(not private.menu_has_orders('dd100000-0000-4000-8000-000000000001'),'Cardápio denies order operation');
select extensions.is((select trial_ends_at from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'),(select trial_ends_at from offers_original_boundary),'downgrade preserves trial end');
select extensions.throws_ok($$update private.billing_signups set trial_ends_at=now()+interval '14 days' where id='dd300000-0000-4000-8000-000000000001'$$,'23514',null,'cannot reset trial directly');
select extensions.throws_ok($$insert into private.billing_signups(tax_document,business_name,responsible_name,email,phone,cycle,payment_method,base_monthly_cents,cycle_months,discount_bps,total_cents,terms_version,management_token_hash,product_code,offer_code) values('00000000001301','Fixture','Fixture','again@example.invalid','11999999999','monthly','pix',4990,1,0,4990,'fixture','offers-fixture-another-token','menu','encomendas')$$,'23505',null,'other offer cannot claim second trial for same CPF/CNPJ');
select extensions.ok(not has_function_privilege('anon','public.backend_billing_change_offer(uuid,text,timestamptz)','execute'),'anon cannot change offers');
select extensions.ok(not has_function_privilege('authenticated','public.backend_billing_change_offer(uuid,text,timestamptz)','execute'),'authenticated cannot bypass billing handler');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"dd800000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.is(public.menu_onboarding_status('dd100000-0000-4000-8000-000000000001')->>'next_step','review','Cardápio does not require an order test');
select extensions.lives_ok($$select public.confirm_menu_review('dd100000-0000-4000-8000-000000000001')$$,'Cardápio review does not insert an order');
select extensions.lives_ok($$select public.set_menu_publication('dd100000-0000-4000-8000-000000000001',true)$$,'Cardápio can publish with WhatsApp');
select extensions.is((select count(*) from public.menu_orders where barbershop_id='dd100000-0000-4000-8000-000000000001'),0::bigint,'Cardápio has no order monitor records');
reset role;
set local role anon;
select extensions.is(public.public_menu('offers-fixture')->'menu'->>'offer_code','cardapio','public flow receives offer from server');
select extensions.is(public.public_menu('offers-fixture')->'menu'->>'whatsapp_phone','5511999999999','public WhatsApp comes from configured number');
select extensions.is(public.public_menu('offers-fixture')->'menu'->>'accepts_delivery','false','Cardápio never offers platform delivery');
select extensions.throws_ok($$select public.public_create_menu_order_v2('offers-fixture','Fixture','','11999999999','pickup',null,'','[{"menu_item_price_id":"dd700000-0000-4000-8000-000000000001","quantity":1,"selections":[]}]',true,'dd900000-0000-4000-8000-000000000001',null,'')$$,'42501',null,'crafted order API call cannot bypass Cardápio');
reset role;
select public.backend_billing_change_offer('dd100000-0000-4000-8000-000000000001','encomendas',(select updated_at from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'));
select extensions.is((select total_cents from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'),4990,'upgrade changes next monthly price');
select extensions.is((select trial_ends_at from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'),(select trial_ends_at from offers_original_boundary),'upgrade preserves original trial end');
set local role anon;
select extensions.lives_ok($$select public.public_create_menu_order_v2('offers-fixture','Fixture','','11999999999','pickup',null,'','[{"menu_item_price_id":"dd700000-0000-4000-8000-000000000001","quantity":1,"selections":[]}]',true,'dd900000-0000-4000-8000-000000000002',null,'')$$,'Encomendas still accepts a complete public order');
reset role;
select extensions.is((select count(*) from public.menu_orders where barbershop_id='dd100000-0000-4000-8000-000000000001'),1::bigint,'only Encomendas creates an order');
update private.billing_signups set cycle='annual',cycle_months=12,discount_bps=1667,total_cents=49900 where id='dd300000-0000-4000-8000-000000000001';
select public.backend_billing_change_offer('dd100000-0000-4000-8000-000000000001','cardapio',(select updated_at from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'));
select extensions.is((select total_cents from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'),29900,'annual Cardápio is exactly 299 reais');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"dd800000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select extensions.is((select count(*) from public.menu_orders where barbershop_id='dd100000-0000-4000-8000-000000000001'),0::bigint,'downgrade removes order-monitor access through RLS');
reset role;
select extensions.is((select count(*) from public.menu_orders where barbershop_id='dd100000-0000-4000-8000-000000000001'),1::bigint,'downgrade retains order history');
select extensions.throws_ok($$update public.business_whatsapp_shares set phone=null where barbershop_id='dd100000-0000-4000-8000-000000000001'$$,'23514',null,'published Cardápio cannot lose WhatsApp');
select public.backend_billing_change_offer('dd100000-0000-4000-8000-000000000001','encomendas',(select updated_at from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'));
select extensions.is((select total_cents from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'),49900,'annual Encomendas is exactly 499 reais');
select extensions.is((select trial_started_at from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'),(select trial_started_at from offers_original_boundary),'multiple switches preserve trial start');
select extensions.throws_ok($$update public.saas_plans set monthly_fee=1 where code='cardapio' and product_id=(select id from public.platform_products where code='menu')$$,'23514',null,'administrative edits cannot diverge from the billing offer');
update private.billing_signups set status='active',access_until=now()+interval '1 month' where id='dd300000-0000-4000-8000-000000000001';
select private.sync_menu_billing_access('dd300000-0000-4000-8000-000000000001');
create temporary table offers_paid_boundary as select access_until from private.billing_signups where id='dd300000-0000-4000-8000-000000000001';
select public.backend_billing_change_offer('dd100000-0000-4000-8000-000000000001','cardapio',(select updated_at from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'));
select extensions.is((select access_until from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'),(select access_until from offers_paid_boundary),'paid downgrade preserves prepaid access');
select extensions.is((select status from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'),'active','paid switch does not become a trial');
select extensions.throws_ok($$select public.backend_billing_change_offer('dd100000-0000-4000-8000-000000000001','encomendas',now()-interval '1 minute')$$,'40001',null,'stale switch cannot overwrite another billing update');
update private.billing_signups set status='past_due',access_until=null,trial_ends_at=now()-interval '1 day' where id='dd300000-0000-4000-8000-000000000001';
select private.sync_menu_billing_access('dd300000-0000-4000-8000-000000000001');
select public.backend_billing_change_offer('dd100000-0000-4000-8000-000000000001','encomendas',(select updated_at from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'));
select extensions.is((select trial_ends_at from private.billing_signups where id='dd300000-0000-4000-8000-000000000001'),now()-interval '1 day','expired trial is never extended by switching');
select extensions.ok(not private.business_product_is_active('dd100000-0000-4000-8000-000000000001','menu'),'switching does not reactivate an unpaid expired account');
select * from extensions.finish();
rollback;
